export const COMPANY_LOGO = 'data:image/jpeg;base64,';

const PRINT_STYLES = `
  * { box-sizing: border-box; margin: 0; padding: 0; }

  /* ── Force ALL text black & bold for printing ── */
  body {
    font-family: Arial, sans-serif;
    font-size: 13px;
    padding: 24px;
    color: #000 !important;
    background: #fff;
  }
  body * {
    color: #000 !important;
    border-color: #555 !important;
    background-color: transparent !important;
    font-weight: 600 !important;
  }

  /* ── Table ── */
  table { width: 100%; border-collapse: collapse; margin-bottom: 12px; font-size: 12px; }
  th, td { border: 1px solid #333 !important; padding: 6px 8px; text-align: left; color: #000 !important; }
  th { background: #e8e8e8 !important; font-weight: 800 !important; }
  tfoot tr td { background: #f0f0f0 !important; font-weight: 800 !important; }

  /* ── Headings ── */
  h1, h2, h3, h4, h5, h6 { color: #000 !important; font-weight: 800 !important; margin: 10px 0 6px; }

  /* ── Badges → plain bordered box ── */
  .badge, span[class*="badge"] {
    display: inline-block;
    padding: 2px 7px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 800 !important;
    border: 1px solid #333 !important;
    color: #000 !important;
    background: #eee !important;
  }

  /* ── Summary/total boxes ── */
  .grand { border: 2px solid #000 !important; padding: 14px; margin-top: 12px;
    display: grid; grid-template-columns: repeat(4,1fr); gap: 12px; text-align: center; }
  .grand-label { font-size: 11px; color: #000 !important; font-weight: 700 !important; text-transform: uppercase; }
  .grand-value { font-size: 17px; font-weight: 800 !important; color: #000 !important; }

  /* ── Signature lines ── */
  .sign-section { display: flex; justify-content: space-between; margin-top: 40px; }
  .sign-line { border-top: 1.5px solid #000 !important; margin-top: 40px; padding-top: 4px;
    font-size: 11px; text-align: center; width: 180px; color: #000 !important; }

  /* ── Carried balance notice ── */
  .carried { background: #f5f5f5 !important; padding: 8px; border: 1px solid #333 !important;
    margin-bottom: 10px; font-size: 12px; font-weight: 700 !important; }

  /* ── Payment summary rows ── */
  .summary { margin-top: 16px; border: 1px solid #333 !important; padding: 12px; }
  .summary-row { display: flex; justify-content: space-between; padding: 4px 0;
    border-bottom: 1px solid #aaa !important; color: #000 !important; }
  .summary-row.grand { font-weight: 800 !important; font-size: 14px;
    border-top: 2px solid #000 !important; margin-top: 4px; padding-top: 8px; }

  /* ── Dark-mode overrides: inline color styles are the problem ── */
  /* Force inline color styles to black */
  [style*="color:#ccc"], [style*="color: #ccc"] { color: #000 !important; }
  [style*="color:#888"], [style*="color: #888"] { color: #000 !important; }
  [style*="color:#666"], [style*="color: #666"] { color: #000 !important; }
  [style*="color:#555"], [style*="color: #555"] { color: #000 !important; }
  [style*="color:#444"], [style*="color: #444"] { color: #000 !important; }
  [style*="color:#333"], [style*="color: #333"] { color: #000 !important; }
  [style*="color:#f87171"] { color: #c00000 !important; }  /* red amounts */
  [style*="color:#4ade80"] { color: #006600 !important; }  /* green paid */
  [style*="color:#eab308"] { color: #7a5c00 !important; }  /* yellow amounts */
  [style*="color:#a78bfa"] { color: #4400bb !important; }  /* purple royalty */
  [style*="color:#f0f0f0"] { color: #000 !important; }
  [style*="color:#e0e0e0"] { color: #000 !important; }
  [style*="color:#fff"],  [style*="color: #fff"]  { color: #000 !important; }
  [style*="color:white"]  { color: #000 !important; }
  [style*="background:#1"] { background: #f5f5f5 !important; }
  [style*="background:#0"] { background: #fff !important; }

  /* ── Remove dark backgrounds from containers ── */
  div[style*="background:#1"], div[style*="background:#0"] { background: #fff !important; }
  div[style*="background:rgb"] { background: #fff !important; }

  /* ── Hide non-print elements ── */
  button, .no-print, [data-no-print] { display: none !important; }

  /* Day header */
  .day-header { background: #e8e8e8 !important; padding: 7px 10px; font-weight: 800 !important;
    font-size: 12px; border: 1px solid #333 !important; margin-top: 8px; color: #000 !important; }

  @media print { body { padding: 10px; } }
`;

const buildDoc = (title, bodyHTML) => {
  return `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8"/>
  <title>${title}</title>
  <style>${PRINT_STYLES}</style>
</head>
<body>
  <div style="text-align:center;margin-bottom:20px;padding-bottom:14px;border-bottom:3px solid #222;">
    <img src="${COMPANY_LOGO}" alt="RC Enterprises"
      style="height:90px;width:auto;object-fit:contain;display:block;margin:0 auto 8px;" />
    <h2 style="margin:0;font-size:22px;font-weight:800;letter-spacing:1px;color:#111;">R.C Enterprises</h2>
    <p style="margin:4px 0 0;font-size:12px;color:#444;">
      Mr. Chand Laluwale &nbsp;&nbsp;|&nbsp;&nbsp; Mr. Roshan Laluwale
    </p>
  </div>
  <h3 style="text-align:center;margin-bottom:16px;font-size:15px;font-weight:700;color:#111;">${title}</h3>
  ${bodyHTML}
  <div style="margin-top:36px;padding-top:10px;border-top:1px solid #ddd;text-align:center;">
    <p style="margin:0;font-size:9px;color:#bbb;letter-spacing:0.5px;">
      Developed by Chaitanya H Daterao &nbsp;&nbsp;|&nbsp;&nbsp; Mob: 9766150846
    </p>
  </div>
  <script>
    document.querySelectorAll('[data-no-print],button').forEach(function(el){el.remove();});
    window.onload = function() { setTimeout(function() { window.print(); window.close(); }, 500); };
  <\/script>
</body>
</html>`;
};

export const openPrintWindow = (htmlBody, title = 'Bill') => {
  const win = window.open('', '_blank', 'width=960,height=750');
  if (!win) { alert('Please allow popups for printing.'); return; }
  win.document.write(buildDoc(title, htmlBody));
  win.document.close();
};

export const printSection = (element, title = 'Bill') => {
  if (!element) { console.warn('printSection: element is null'); return; }
  if (typeof element === 'string') {
    openPrintWindow(element, title);
    return;
  }
  const clone = element.cloneNode(true);
  clone.querySelectorAll('[data-no-print]').forEach(el => el.remove());
  clone.querySelectorAll('button').forEach(el => el.remove());
  openPrintWindow(clone.innerHTML, title);
};